import React, { useEffect, useState } from 'react';

export default function Diary() {
  const [entries, setEntries] = useState([]);

  useEffect(() => {
    async function fetchData() {
      const sheetId = "1Su9vcEcDmH02nzqtkYhO5dK-TxorHzRGzZbF8OHTXb8";

      const res = await fetch(
        `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Diary Points!A2:C1000?key=AIzaSyBZchFlW_joIa7CnSSacm8oalKQqYayhyk`
      );
      const data = await res.json();

      const parsed = (data.values || [])
        .map(([name, , points]) => ({
          name,
          points: parseInt(points || "0") || 0,
        }))
        .sort((a, b) => b.points - a.points);

      setEntries(parsed);
    }

    fetchData();
  }, []);

  return (
    <div className="p-4 text-white">
      <h1 className="text-2xl font-bold mb-4">📘 Diary Point Leaderboard</h1>
      <div className="bg-gray-800 rounded-lg shadow overflow-x-auto">
        <table className="min-w-full text-sm text-left">
          <thead className="bg-gray-700 text-gray-200">
            <tr>
              <th className="px-4 py-2">Rank</th>
              <th className="px-4 py-2">Username</th>
              <th className="px-4 py-2">Points</th>
            </tr>
          </thead>
          <tbody>
            {entries.map((entry, i) => (
              <tr key={i} className="border-b border-gray-700">
                <td className="px-4 py-2">{i + 1}</td>
                <td className="px-4 py-2">{entry.name}</td>
                <td className="px-4 py-2 text-blue-400">{entry.points}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
