// src/lib/wikiImage.js
// No external deps needed. Uses the OSRS Wiki MediaWiki API (CORS friendly with origin=*).

function sanitizeForWiki(name) {
  return (name || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function fileTitleFromName(name) {
  // Convert “Armadyl crossbow” -> “File:Armadyl_crossbow_detail.png”
  return `File:${name.replace(/ /g, '_')}_detail.png`;
}

async function fetchJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// Try to resolve a File:... page to a direct image URL
async function getImageInfoFromFileTitle(fileTitle) {
  const url = `https://oldschool.runescape.wiki/api.php?action=query&titles=${encodeURIComponent(fileTitle)}&prop=imageinfo&iiprop=url&format=json&origin=*`;

  const data = await fetchJson(url);
  const pages = data?.query?.pages || {};
  const first = Object.values(pages)[0];
  const ii = first?.imageinfo?.[0];
  return ii?.url || null;
}

// Search the wiki for either a File: page or fallback to a normal page, then pull images
async function searchBestImage(name) {
  const q = sanitizeForWiki(name);

  // 1) Try searching for File: pages directly (namespace 6)
  const fileSearchUrl = `https://oldschool.runescape.wiki/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&srnamespace=6&format=json&origin=*`;
  const fileSearch = await fetchJson(fileSearchUrl);
  const fileHit = fileSearch?.query?.search?.[0];
  if (fileHit?.title?.startsWith('File:')) {
    const url = await getImageInfoFromFileTitle(fileHit.title);
    if (url) return url;
  }

  // 2) Otherwise search normal pages, then fetch their images and pick the closest *_detail.png
  const pageSearchUrl = `https://oldschool.runescape.wiki/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&format=json&origin=*`;
  const pageSearch = await fetchJson(pageSearchUrl);
  const pageHit = pageSearch?.query?.search?.[0];
  const pageId = pageHit?.pageid;

  if (!pageId) return null;

  const imagesUrl = `https://oldschool.runescape.wiki/api.php?action=query&pageids=${pageId}&prop=images&imlimit=500&format=json&origin=*`;
  const imagesData = await fetchJson(imagesUrl);
  const imgs = imagesData?.query?.pages?.[pageId]?.images || [];

  // Prefer *_detail.png
  const detail = imgs.find(im => /_detail\.png$/i.test(im.title));
  const chosen = detail?.title || imgs[0]?.title;
  if (!chosen) return null;

  const finalUrl = await getImageInfoFromFileTitle(chosen);
  return finalUrl;
}

/**
 * Main helper you call.
 * @param {string} itemName
 * @returns {Promise<string|null>} wiki image URL or null
 */
export async function findBestWikiImage(itemName) {
  const clean = sanitizeForWiki(itemName);

  // First, try the most common pattern directly:
  const directFileTitle = fileTitleFromName(clean);
  const directUrl = await getImageInfoFromFileTitle(directFileTitle);
  if (directUrl) return directUrl;

  // Fallback: do a search + fuzzy match
  return await searchBestImage(clean);
}
