import React, { useEffect, useState } from 'react';

export default function NewsFeed() {
  const [updates, setUpdates] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchWikiUpdates() {
      try {
        const wikiUrl = 'https://oldschool.runescape.wiki/w/Game_updates';
        const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(wikiUrl)}`;

        const res = await fetch(proxyUrl);
        if (!res.ok) throw new Error(`HTTP error ${res.status}`);

        const html = await res.text();
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        // Find the <h3> with text "2025"
        const headings = Array.from(doc.querySelectorAll('.mw-parser-output h3'));
        const heading2025 = headings.find(h => h.textContent.includes('2025'));

        if (!heading2025) throw new Error('Could not find 2025 heading');

        // Get the next <ul> after the 2025 heading
        let ul = heading2025.nextElementSibling;
        while (ul && ul.tagName !== 'UL') {
          ul = ul.nextElementSibling;
        }

        if (!ul) throw new Error('No updates list found after 2025 heading');

        const items = Array.from(ul.querySelectorAll('li')).slice(0, 10); // Limit to top 10

        const parsed = items.map(li => {
          const text = li.textContent.trim();
          const linkEl = li.querySelector('a');
          const href = linkEl?.href
            ? `https://oldschool.runescape.wiki${linkEl.getAttribute('href')}`
            : 'https://oldschool.runescape.wiki/w/Game_updates';

          return {
            text,
            link: href,
          };
        });

        setUpdates(parsed);
      } catch (err) {
        console.error('[NewsFeed] Update fetch error:', err);
        setError(err.message);
      }
    }

    fetchWikiUpdates();
  }, []);

  return (
    <div className="bg-gray-800 text-white rounded p-4 shadow mt-6">
      <h2 className="text-xl font-semibold mb-2">📰 Latest OSRS Wiki Updates (2025)</h2>
      {error && <p className="text-red-400">Error: {error}</p>}
      {!error && updates.length === 0 && <p>Loading updates...</p>}
      <ul className="space-y-2">
        {updates.map((u, i) => (
          <li key={i}>
            <a
              href={u.link}
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-400 hover:underline"
            >
              {u.text}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}
