import React, { useEffect, useState } from "react";
import Fuse from "fuse.js";

export default function Search() {
  const [query, setQuery] = useState("");
  const [data, setData] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  const ignoredNames = [
    "Staff", "Wrath", "Zenyte", "Onyx", "Dragonstone", "Beast",
    "1 Nana", "2 Nana", "3 Nana", "Serenist", "", undefined
  ];

  useEffect(() => {
    async function loadData() {
      const sheetId = "1Su9vcEcDmH02nzqtkYhO5dK-TxorHzRGzZbF8OHTXb8";
      const apiKey = "AIzaSyBZchFlW_joIa7CnSSacm8oalKQqYayhyk";
      const url = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Front Page!A2:H1000?key=${apiKey}`;

      const res = await fetch(url);
      const json = await res.json();
      const rows = json.values || [];

      const parsed = rows
        .map((row) => ({
          name: row[0]?.trim(),
          region: row[1] || "",
          joinDate: row[2] || "",
          daysInClan: row[3] || "",
          rank: row[4] || "",
          splits: row[5] || "0",
          drops: row[6] || "0",
          diaryPoints: row[7] || "0",
        }))
        .filter((entry) => entry.name && !ignoredNames.includes(entry.name));

      setData(parsed);
    }

    loadData();
  }, []);

  useEffect(() => {
    if (!query || !data.length) {
      setFiltered([]);
      setSuggestions([]);
      return;
    }

    const fuse = new Fuse(data, {
      keys: ["name"],
      threshold: 0.4,
    });

    const result = fuse.search(query);
    setSuggestions(result.slice(0, 5).map((res) => res.item.name));
    setFiltered(result.map((res) => res.item));
  }, [query, data]);

  const handleSuggestionClick = (name) => {
    const match = data.find((item) => item.name === name);
    setQuery(name);
    setFiltered(match ? [match] : []);
    setSuggestions([]);
  };

  return (
    <div className="p-4 text-white">
      <h1 className="text-2xl font-bold mb-2">🔍 Search User</h1>
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Enter player name"
        className="p-2 rounded bg-gray-800 border border-gray-600 text-white w-full max-w-md mb-2"
      />
      {suggestions.length > 0 && (
        <ul className="mb-4 bg-gray-800 rounded p-2">
          {suggestions.map((s, i) => (
            <li
              key={i}
              className="cursor-pointer hover:underline text-sm"
              onClick={() => handleSuggestionClick(s)}
            >
              {s}
            </li>
          ))}
        </ul>
      )}
      {filtered.length === 0 && query ? (
        <p>No results found for "{query}"</p>
      ) : (
        filtered.map((user, i) => (
          <div key={i} className="bg-gray-800 rounded p-4 mb-3 shadow">
            <h2 className="text-lg font-semibold">{user.name}</h2>
            <p>🌍 Region: {user.region}</p>
            <p>📅 Join Date: {user.joinDate}</p>
            <p>📆 Days in Clan: {user.daysInClan}</p>
            <p className="text-green-400">💰 Total Splits: {user.splits}M GP</p>
            <p className="text-yellow-400">🎯 Drops: {user.drops}</p>
            <p className="text-blue-400">📘 Diary Points: {user.diaryPoints}</p>
          </div>
        ))
      )}
    </div>
  );
}
