import React from 'react';
import { useNavigate } from 'react-router-dom';

export default function Events() {
  const navigate = useNavigate();

  return (
    <div className="p-8 flex justify-center items-center min-h-screen gap-12">
      {/* Bounties Button */}
      <button onClick={() => navigate('/bounties')} className="hover:scale-105 transition-transform duration-200">
        <img
          src={`${process.env.PUBLIC_URL}/images/bounties.png`}
          alt="Bounties"
          className="w-64 h-auto rounded-lg shadow-lg"
        />
      </button>

      {/* Bingo Button */}
      <button onClick={() => navigate('/bingo')} className="hover:scale-105 transition-transform duration-200">
        <img
          src={`${process.env.PUBLIC_URL}/images/bingo.png`}
          alt="Bingo"
          className="w-64 h-auto rounded-lg shadow-lg"
        />
      </button>
    </div>
  );
}
