import React, { useEffect, useState } from 'react';
import OsrsItemImage from '../components/OsrsItemImage';

const SHEET_ID = '1en3zy9WY546I2V9iqk9GutkELvkI2N1snyebLEkXtwc';
const API_KEY = 'AIzaSyBZchFlW_joIa7CnSSacm8oalKQqYayhyk';
const RANGE = "Bounties!B3:H";

function sanitizeItemName(name) {
  return name?.replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/ /g, '_');
}

export default function BountiesPage() {
  const [openBounties, setOpenBounties] = useState([]);
  const [closedBounties, setClosedBounties] = useState([]);

  useEffect(() => {
    fetch(`https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${RANGE}?key=${API_KEY}`)
      .then(res => res.json())
      .then(json => {
        const rows = json.values || [];
        const open = [];
        const closed = [];

        for (let row of rows) {
          const [name, value, claimed, acquiredBy, date, screenshot, paid] = row;

          if (!name || !value) continue;

          const entry = {
            name,
            value,
            claimed: claimed === 'Y',
            acquiredBy,
            date,
            screenshot,
            paid,
          };

          if (entry.claimed) closed.push(entry);
          else open.push(entry);
        }

        setOpenBounties(open);
        setClosedBounties(closed);
      });
  }, []);

  const renderBountyCard = (bounty, idx) => (
    <div key={idx} className="bg-gray-900 p-4 rounded shadow">
      <OsrsItemImage name={bounty.name} className="w-8 h-8 inline-block mr-2" />
      <div className="text-lg font-semibold">{bounty.name}</div>
      <div className="text-sm text-gray-400">Reward: {bounty.value}</div>

      {bounty.claimed ? (
        <>
          <div className="text-green-400 mt-2">✅ Claimed</div>
          <div className="text-sm">By: {bounty.acquiredBy || 'Unknown'}</div>
          <div className="text-sm">Date: {bounty.date || 'Unknown'}</div>
          {bounty.screenshot && (
            <a
              href={bounty.screenshot}
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-400 underline text-sm"
            >
              View Screenshot
            </a>
          )}
        </>
      ) : (
        <div className="text-yellow-400 mt-2">🕒 Available</div>
      )}
    </div>
  );

  return (
    <div className="p-4 text-white">
      <h1 className="text-2xl font-bold mb-4">🎯 Bounties</h1>

      <div className="mb-6">
        <h2 className="text-xl font-semibold mb-2 text-yellow-300">Open Bounties</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {openBounties.length > 0 ? openBounties.map(renderBountyCard) : <p>No open bounties.</p>}
        </div>
      </div>

      <div>
        <h2 className="text-xl font-semibold mb-2 text-green-300">Closed Bounties</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {closedBounties.length > 0 ? closedBounties.map(renderBountyCard) : <p>No closed bounties yet.</p>}
        </div>
      </div>
    </div>
  );
}
