import React, { useEffect, useState } from "react";

const DISCORD_INVITE = "https://discord.gg/V552P6Hy";
const GUILD_ID = "1146456264212760586";

export default function DiscordPanel() {
  const [widgetData, setWidgetData] = useState(null);

  useEffect(() => {
    fetch(`https://discord.com/api/guilds/${GUILD_ID}/widget.json`)
      .then((res) => res.json())
      .then((data) => setWidgetData(data))
      .catch(() => setWidgetData(null));
  }, []);

  return (
    <div className="p-4 bg-[#2b2d31] rounded-xl text-white shadow-lg space-y-4 border border-gray-700">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">🎮 Mercenary PvM</h2>
          <p className="text-gray-400 text-sm">
            {widgetData ? `🟢 ${widgetData.presence_count} online` : "🔌 Offline"}
          </p>
        </div>
        <a
          href={DISCORD_INVITE}
          target="_blank"
          rel="noopener noreferrer"
          className="bg-indigo-600 hover:bg-indigo-700 px-4 py-2 rounded-md text-sm"
        >
          Join Discord
        </a>
      </div>

      {widgetData?.instant_invite && (
        <div>
          <img
            src={`https://cdn.discordapp.com/icons/${GUILD_ID}/${GUILD_ID}.png`}
            alt="Discord banner"
            className="w-full h-32 object-cover rounded-lg mb-2"
            onError={(e) => (e.target.style.display = "none")}
          />
        </div>
      )}

      {widgetData?.members?.length > 0 && (
        <div>
          <h3 className="text-lg font-semibold mb-2">Online Members</h3>
          <div className="flex flex-wrap gap-3">
            {widgetData.members.slice(0, 20).map((member, i) => (
              <div key={i} className="flex flex-col items-center text-sm w-12">
                <img
                  src={member.avatar_url}
                  alt={member.username}
                  className="w-10 h-10 rounded-full border border-gray-700"
                />
                <span className="truncate w-full text-center">{member.username}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="mt-4">
        <iframe
          src={`https://discord.com/widget?id=${GUILD_ID}&theme=dark`}
          width="100%"
          height="300"
          allowTransparency="true"
          frameBorder="0"
          sandbox="allow-popups allow-popups-to-escape-sandbox allow-same-origin allow-scripts"
          className="rounded-lg border border-gray-800"
        ></iframe>
      </div>
    </div>
  );
}
