import React, { useEffect, useState } from 'react';

export default function Splits() {
  const [splitData, setSplitData] = useState([]);
  const [diaryLeaders, setDiaryLeaders] = useState([]);
  const [sortDescending, setSortDescending] = useState(true);

  useEffect(() => {
    async function fetchData() {
      const sheetId = '1Su9vcEcDmH02nzqtkYhO5dK-TxorHzRGzZbF8OHTXb8';
      const apiKey = 'AIzaSyBZchFlW_joIa7CnSSacm8oalKQqYayhyk';

      const ignoredNames = [
        "Staff",
        "Wrath",
        "Zenyte",
        "Onyx",
        "Dragonstone",
        "Beast",
        "1 Nana",
        "2 Nana",
        "3 Nana",
        "Serenist"
      ];

      try {
        // Fetch both sheets
        const [splitsRes, diaryRes] = await Promise.all([
          fetch(`https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Clan splits?key=${apiKey}`),
          fetch(`https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Diary Points?key=${apiKey}`)
        ]);

        const splitsData = await splitsRes.json();
        const diaryData = await diaryRes.json();

        // Parse split data
        const splitEntries = (splitsData.values || [])
          .slice(1)
          .map(row => {
            const name = row[0];
            const gp = row[1] ? parseInt(row[1].replace(/[^0-9]/g, '')) : 0;
            return { name, gp };
          })
          .filter(entry => entry.name && !isNaN(entry.gp) && !ignoredNames.includes(entry.name));

        const sortedSplits = splitEntries.sort((a, b) =>
          sortDescending ? b.gp - a.gp : a.gp - b.gp
        );

        // Parse diary data
        const diaryEntries = (diaryData.values || [])
          .slice(1)
          .map(row => {
            const name = row[0];
            const points = row[2] ? parseInt(row[2].replace(/[^0-9]/g, '')) : 0;
            return { name, points };
          })
          .filter(entry => entry.name && !isNaN(entry.points) && !ignoredNames.includes(entry.name))
          .sort((a, b) => b.points - a.points)
          .slice(0, 10);

        setSplitData(sortedSplits);
        setDiaryLeaders(diaryEntries);
      } catch (err) {
        console.error('Error loading splits or diary data:', err);
      }
    }

    fetchData();
  }, [sortDescending]);

  return (
    <div className="p-6 text-white">
      <h1 className="text-3xl font-bold mb-4">💰 Clan Split Leaderboard</h1>

      {/* Top 10 Sections */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div>
          <h2 className="text-xl font-semibold mb-2">🥇 Top 10 Split Earners</h2>
          <ul className="bg-gray-800 rounded-lg shadow">
            {splitData.slice(0, 10).map((entry, idx) => (
              <li
                key={idx}
                className="flex justify-between items-center px-4 py-2 border-b border-gray-700"
              >
                <span>{idx + 1}. {entry.name}</span>
                <span className="text-green-400">{entry.gp.toLocaleString()}M GP</span>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h2 className="text-xl font-semibold mb-2">📘 Top 10 Diary Points</h2>
          <ul className="bg-gray-800 rounded-lg shadow">
            {diaryLeaders.map((entry, idx) => (
              <li
                key={idx}
                className="flex justify-between items-center px-4 py-2 border-b border-gray-700"
              >
                <span>{idx + 1}. {entry.name}</span>
                <span className="text-blue-400">{entry.points} pts</span>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Sort Button */}
      <div className="mb-4">
        <button
          onClick={() => setSortDescending(!sortDescending)}
          className="bg-gray-700 text-white px-4 py-2 rounded hover:bg-gray-600"
        >
          Sort: {sortDescending ? 'Highest → Lowest' : 'Lowest → Highest'}
        </button>
      </div>

      {/* Full Split Table */}
      <table className="min-w-full bg-gray-800 text-white rounded-lg overflow-hidden">
        <thead>
          <tr className="bg-gray-700">
            <th className="py-2 px-4 text-left">Rank</th>
            <th className="py-2 px-4 text-left">Name</th>
            <th className="py-2 px-4 text-right">Total GP</th>
          </tr>
        </thead>
        <tbody>
          {splitData.map((entry, idx) => (
            <tr key={idx} className="border-t border-gray-700">
              <td className="py-2 px-4">{idx + 1}</td>
              <td className="py-2 px-4">{entry.name}</td>
              <td className="py-2 px-4 text-right text-green-400">
                {entry.gp.toLocaleString()}M GP
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
