// src/components/OsrsItemImage.js
import React, { useEffect, useState } from 'react';
import { findBestWikiImage } from '../lib/wikiImage';

export default function OsrsItemImage({ name, className = 'w-8 h-8 inline-block mr-2' }) {
  const [src, setSrc] = useState(`/items/${name.replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/ /g, '_')}.webp`);
  const [triedWiki, setTriedWiki] = useState(false);

  useEffect(() => {
    setSrc(`/items/${name.replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/ /g, '_')}.webp`);
    setTriedWiki(false);
  }, [name]);

  const handleError = async () => {
    if (triedWiki) return; // prevent infinite loops
    setTriedWiki(true);
    try {
      const bestUrl = await findBestWikiImage(name);
      if (bestUrl) setSrc(bestUrl);
    } catch (e) {
      console.error('Wiki lookup failed for', name, e);
    }
  };

  return (
    <img
      src={src}
      alt={name}
      className={className}
      onError={handleError}
    />
  );
}
