import React, { useEffect, useState } from 'react';

export default function UploadsPage() {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [lightboxIndex, setLightboxIndex] = useState(null);

  useEffect(() => {
    async function fetchImages() {
      try {
        const res = await fetch(`https://141.98.157.23/api/uploads`);
        const data = await res.json();
        setImages(data);
      } catch (err) {
        console.error('Failed to fetch images:', err);
      } finally {
        setLoading(false);
      }
    }

    fetchImages();
    const interval = setInterval(fetchImages, 60000);
    return () => clearInterval(interval);
  }, []);

  const openLightbox = (index) => setLightboxIndex(index);
  const closeLightbox = () => setLightboxIndex(null);
  const prevImage = () => setLightboxIndex((i) => (i > 0 ? i - 1 : images.length - 1));
  const nextImage = () => setLightboxIndex((i) => (i + 1) % images.length);

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-4 text-white">🖼️ RuneScape Screenshot Gallery</h1>

      {loading ? (
        <p className="text-white">Loading screenshots...</p>
      ) : images.length === 0 ? (
        <p className="text-gray-400">No images found.</p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
          {images.map((img, idx) => (
            <div key={idx} className="bg-gray-900 p-4 rounded-lg shadow">
              <img
                src={img.url}
                alt={`Upload by ${img.author}`}
                className="w-full h-auto rounded-lg hover:opacity-90 cursor-pointer"
                onClick={() => openLightbox(idx)}
              />
              <div className="mt-2 text-sm text-gray-300">
                <p><strong>{img.author}</strong></p>
                <p>{new Date(parseInt(img.timestamp)).toLocaleString()}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Lightbox Overlay */}
      {lightboxIndex !== null && (
        <div className="fixed inset-0 z-50 bg-black bg-opacity-90 flex flex-col items-center justify-center">
          <button
            onClick={closeLightbox}
            className="absolute top-4 right-4 text-white text-3xl font-bold"
          >
            &times;
          </button>

          <div className="flex items-center justify-center space-x-4">
            <button onClick={prevImage} className="text-white text-4xl">&#8592;</button>
            <img
              src={images[lightboxIndex].url}
              alt="Slideshow"
              className="max-h-[80vh] max-w-[90vw] rounded shadow-lg"
            />
            <button onClick={nextImage} className="text-white text-4xl">&#8594;</button>
          </div>

          <div className="text-white mt-4 text-sm text-center">
            <p><strong>{images[lightboxIndex].author}</strong></p>
            <p>{new Date(parseInt(images[lightboxIndex].timestamp)).toLocaleString()}</p>
          </div>
        </div>
      )}
    </div>
  );
}
